"use client";

import { AlertTriangle, Pencil, Plus, ShieldCheck, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createAccessGroup,
  deleteAccessGroup,
  getAccessGroupRoles,
  getAccessGroups,
  type AccessGroupListItem,
  type AccessGroupRoleItem,
  type UpsertAccessGroupRequest,
  updateAccessGroup,
} from "@/lib/api/access-groups";

type FormState = UpsertAccessGroupRequest;

const initialFormState: FormState = {
  name: "",
  roleIds: [],
};

type AccessGroupsPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function AccessGroupsPage({ searchParams }: AccessGroupsPageProps) {
  const [items, setItems] = useState<AccessGroupListItem[]>([]);
  const [roles, setRoles] = useState<AccessGroupRoleItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const [groupsData, rolesData] = await Promise.all([getAccessGroups(), getAccessGroupRoles()]);
      setItems(groupsData);
      setRoles(rolesData);
    } catch {
      setError("Не удалось загрузить группы доступа");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onEdit = (item: AccessGroupListItem) => {
    setEditingId(item.id);
    setForm({
      name: item.name,
      roleIds: [...item.roleIds],
    });
    setError(null);
    setMessage(null);
  };

  const onDelete = async (item: AccessGroupListItem) => {
    const shouldDelete = window.confirm(`Удалить группу доступа '${item.name}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteAccessGroup(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Группа доступа удалена");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось удалить группу доступа");
      }
    }
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      if (editingId) {
        await updateAccessGroup(editingId, form);
        setMessage("Группа доступа обновлена");
      } else {
        await createAccessGroup(form);
        setMessage("Группа доступа создана");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить группу доступа");
      }
    } finally {
      setIsSaving(false);
    }
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Группа доступа для редактирования не найдена");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const toggleRole = (roleId: string, checked: boolean) => {
    setForm((prev) => ({
      ...prev,
      roleIds: checked ? Array.from(new Set([...prev.roleIds, roleId])) : prev.roleIds.filter((id) => id !== roleId),
    }));
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Группы доступа</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ShieldCheck className="h-5 w-5" />
            Группы доступа
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Название</th>
                  <th className="px-3 py-2 font-medium">Роли</th>
                  <th className="px-3 py-2 font-medium">Групп пользователей</th>
                  <th className="px-3 py-2 font-medium">Тип</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.name}</td>
                    <td className="px-3 py-2">
                      {item.roles.length > 0 ? item.roles.map((role) => role.description || role.name).join(", ") : "—"}
                    </td>
                    <td className="px-3 py-2">{item.usersGroupsCount}</td>
                    <td className="px-3 py-2">{item.isBuiltIn ? "Системная" : "Пользовательская"}</td>
                    <td className="px-3 py-2">
                      {item.isBuiltIn ? (
                        <span className="text-xs text-muted-foreground">Недоступно</span>
                      ) : (
                        <div className="flex gap-2">
                          <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                            <Pencil className="h-4 w-4" />
                          </Button>
                          <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>
            {editingItem ? `Изменение '${editingItem.name}'` : "Новая группа доступа"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Наименование</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.name}
                onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-2">
              <div className="text-sm font-medium">Роли</div>
              <div className="max-h-56 space-y-2 overflow-auto rounded-md border p-2">
                {roles.map((role) => (
                  <label key={role.id} className="flex items-center gap-2 text-sm">
                    <input
                      type="checkbox"
                      checked={form.roleIds.includes(role.id)}
                      onChange={(event) => toggleRole(role.id, event.target.checked)}
                    />
                    <span>{role.description || role.name}</span>
                  </label>
                ))}
              </div>
            </div>

            {error && <div className="text-sm text-destructive">{error}</div>}
            {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

            <div className="flex gap-2">
              <Button type="submit" disabled={isSaving}>
                <Plus className="h-4 w-4" />
                {editingItem ? "Сохранить" : "Создать"}
              </Button>
              {editingItem && (
                <Button type="button" variant="outline" onClick={resetForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

