"use client";

import { AlertTriangle, KeyRound, Pencil, Plus, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createCredential,
  deleteCredential,
  getCredentials,
  type CredentialsListItem,
  type UpsertCredentialsRequest,
  updateCredential,
} from "@/lib/api/credentials";

type FormState = UpsertCredentialsRequest;

const initialFormState: FormState = {
  name: "",
  isToken: false,
  token: "",
  user: "",
  password: "",
  defaultForClusters: false,
  defaultV8Admin: false,
  defaultConfigRepositoriesAdmin: false,
};

type CredentialsPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function CredentialsPage({ searchParams }: CredentialsPageProps) {
  const [items, setItems] = useState<CredentialsListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const data = await getCredentials();
      setItems(data);
    } catch {
      setError("Не удалось загрузить учетные данные");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onEdit = (item: CredentialsListItem) => {
    setEditingId(item.id);
    setForm({
      name: item.name,
      isToken: item.isToken,
      token: item.token,
      user: item.user,
      password: item.password ?? "",
      defaultForClusters: item.defaultForClusters,
      defaultV8Admin: item.defaultV8Admin,
      defaultConfigRepositoriesAdmin: item.defaultConfigRepositoriesAdmin,
    });
    setError(null);
    setMessage(null);
  };

  const onDelete = async (item: CredentialsListItem) => {
    const shouldDelete = window.confirm(`Удалить '${item.name}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteCredential(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Запись удалена");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось удалить запись");
      }
    }
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      if (editingId) {
        await updateCredential(editingId, form);
        setMessage("Запись обновлена");
      } else {
        await createCredential(form);
        setMessage("Запись создана");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить запись");
      }
    } finally {
      setIsSaving(false);
    }
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Учетные данные для редактирования не найдены");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const onTokenModeChanged = (checked: boolean) => {
    setForm((prev) => ({
      ...prev,
      isToken: checked,
      token: checked ? prev.token : "",
      user: checked ? "" : prev.user,
      password: checked ? "" : prev.password,
      defaultForClusters: checked ? false : prev.defaultForClusters,
      defaultV8Admin: checked ? false : prev.defaultV8Admin,
      defaultConfigRepositoriesAdmin: checked ? false : prev.defaultConfigRepositoriesAdmin,
    }));
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Учетные данные и токены</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <KeyRound className="h-5 w-5" />
            Учетные данные и токены
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Имя</th>
                  <th className="px-3 py-2 font-medium">Тип</th>
                  <th className="px-3 py-2 font-medium">По умолчанию</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.name}</td>
                    <td className="px-3 py-2">{item.isToken ? "Токен" : "Логин/пароль"}</td>
                    <td className="px-3 py-2">
                      {item.isToken
                        ? "—"
                        : [
                            item.defaultForClusters ? "Кластеры" : null,
                            item.defaultV8Admin ? "Базы" : null,
                            item.defaultConfigRepositoriesAdmin ? "Хранилища" : null,
                          ]
                            .filter(Boolean)
                            .join(", ") || "Нет"}
                    </td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2">
                        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>
            {editingItem ? `Изменение '${editingItem.name}'` : "Новые учетные данные или токен"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Наименование</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.name}
                onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))}
                required
              />
            </div>

            <label className="flex items-center gap-2 text-sm">
              <input type="checkbox" checked={form.isToken} onChange={(event) => onTokenModeChanged(event.target.checked)} />
              Это токен
            </label>

            {form.isToken ? (
              <div className="space-y-1">
                <label className="text-sm">Токен</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  value={form.token}
                  onChange={(event) => setForm((prev) => ({ ...prev, token: event.target.value }))}
                  required
                />
              </div>
            ) : (
              <>
                <div className="space-y-1">
                  <label className="text-sm">Пользователь</label>
                  <input
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                    value={form.user}
                    onChange={(event) => setForm((prev) => ({ ...prev, user: event.target.value }))}
                    required
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-sm">Пароль</label>
                  <input
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                    type="password"
                    value={form.password}
                    onChange={(event) => setForm((prev) => ({ ...prev, password: event.target.value }))}
                    required
                  />
                </div>

                <label className="flex items-center gap-2 text-sm">
                  <input
                    type="checkbox"
                    checked={form.defaultForClusters}
                    onChange={(event) => setForm((prev) => ({ ...prev, defaultForClusters: event.target.checked }))}
                  />
                  Администратор кластера по умолчанию
                </label>
                <label className="flex items-center gap-2 text-sm">
                  <input
                    type="checkbox"
                    checked={form.defaultV8Admin}
                    onChange={(event) => setForm((prev) => ({ ...prev, defaultV8Admin: event.target.checked }))}
                  />
                  Администратор инф. баз по умолчанию
                </label>
                <label className="flex items-center gap-2 text-sm">
                  <input
                    type="checkbox"
                    checked={form.defaultConfigRepositoriesAdmin}
                    onChange={(event) =>
                      setForm((prev) => ({ ...prev, defaultConfigRepositoriesAdmin: event.target.checked }))
                    }
                  />
                  Администратор хранилищ по умолчанию
                </label>
              </>
            )}

            {error && <div className="text-sm text-destructive">{error}</div>}
            {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

            <div className="flex gap-2">
              <Button type="submit" disabled={isSaving}>
                <Plus className="h-4 w-4" />
                {editingItem ? "Сохранить" : "Создать"}
              </Button>
              {editingItem && (
                <Button type="button" variant="outline" onClick={resetForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

