"use client";

import { AlertTriangle, Database, Pencil, Plus, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createDbms,
  deleteDbms,
  getDbmsList,
  type DbmsListItem,
  type DbmsType,
  type UpsertDbmsRequest,
  updateDbms,
} from "@/lib/api/dbms";

type FormState = UpsertDbmsRequest;

const initialFormState: FormState = {
  name: "",
  type: "ClickHouse",
  host: "",
  port: 8123,
};

type DbmsPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function DbmsPage({ searchParams }: DbmsPageProps) {
  const [items, setItems] = useState<DbmsListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const data = await getDbmsList();
      setItems(data);
    } catch {
      setError("Не удалось загрузить СУБД");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onEdit = (item: DbmsListItem) => {
    setEditingId(item.id);
    setForm({
      name: item.name,
      type: item.type,
      host: item.host,
      port: item.port,
    });
    setError(null);
    setMessage(null);
  };

  const onDelete = async (item: DbmsListItem) => {
    const shouldDelete = window.confirm(`Удалить СУБД '${item.name}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteDbms(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("СУБД удалена");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось удалить СУБД");
      }
    }
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("СУБД для редактирования не найдена");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const onTypeChanged = (type: DbmsType) => {
    setForm((prev) => ({
      ...prev,
      type,
      port: 8123,
    }));
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      if (editingId) {
        await updateDbms(editingId, form);
        setMessage("СУБД обновлена");
      } else {
        await createDbms(form);
        setMessage("СУБД создана");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить СУБД");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>СУБД</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Database className="h-5 w-5" />
            СУБД
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Наименование</th>
                  <th className="px-3 py-2 font-medium">Тип</th>
                  <th className="px-3 py-2 font-medium">Хост</th>
                  <th className="px-3 py-2 font-medium">Порт</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.name}</td>
                    <td className="px-3 py-2">{item.type}</td>
                    <td className="px-3 py-2">{item.host}</td>
                    <td className="px-3 py-2">{item.port}</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2">
                        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>{editingItem ? `Изменение '${editingItem.name}'` : "Новая СУБД"}</CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Наименование</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.name}
                onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Тип</label>
              <select
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.type}
                onChange={(event) => onTypeChanged(event.target.value as DbmsType)}
              >
                <option value="ClickHouse">ClickHouse</option>
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-sm">Хост</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.host}
                onChange={(event) => setForm((prev) => ({ ...prev, host: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Порт</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                type="number"
                min={1}
                value={form.port}
                onChange={(event) => setForm((prev) => ({ ...prev, port: Number(event.target.value) || 0 }))}
                required
              />
            </div>

            {error && <div className="text-sm text-destructive">{error}</div>}
            {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

            <div className="flex gap-2">
              <Button type="submit" disabled={isSaving}>
                <Plus className="h-4 w-4" />
                {editingItem ? "Сохранить" : "Создать"}
              </Button>
              {editingItem && (
                <Button type="button" variant="outline" onClick={resetForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

