"use client";

import { AlertTriangle, FileCode2, Pencil, Plus, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createFile,
  deleteFile,
  getFiles,
  type FileListItem,
  updateFile,
} from "@/lib/api/files";

type CreateFormState = {
  name: string;
  version: string;
  file: File | null;
};

type EditFormState = {
  name: string;
  version: string;
};

const initialCreateForm: CreateFormState = {
  name: "",
  version: "",
  file: null,
};

const initialEditForm: EditFormState = {
  name: "",
  version: "",
};

type FilesPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function FilesPage({ searchParams }: FilesPageProps) {
  const [items, setItems] = useState<FileListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [createForm, setCreateForm] = useState<CreateFormState>(initialCreateForm);
  const [editForm, setEditForm] = useState<EditFormState>(initialEditForm);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const data = await getFiles();
      setItems(data);
    } catch {
      setError("Не удалось загрузить файлы");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetCreateForm = () => {
    setCreateForm(initialCreateForm);
  };

  const resetEditForm = () => {
    setEditingId(null);
    setEditForm(initialEditForm);
  };

  const onEdit = (item: FileListItem) => {
    setEditingId(item.id);
    setEditForm({
      name: item.name,
      version: item.version,
    });
    setError(null);
    setMessage(null);
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetEditForm();
      resetCreateForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Файл для редактирования не найден");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items]);

  const onDelete = async (item: FileListItem) => {
    const shouldDelete = window.confirm(`Удалить файл '${item.name}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteFile(item.id);
      await loadData();

      if (editingId === item.id) {
        resetEditForm();
      }

      setMessage("Файл удален");
    } catch {
      setError("Не удалось удалить файл");
    }
  };

  const onCreate = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!createForm.file) {
      setError("Прикрепите файл");
      return;
    }

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      await createFile({
        name: createForm.name,
        version: createForm.version,
        file: createForm.file,
      });

      await loadData();
      resetCreateForm();
      setMessage("Файл создан");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else if (e instanceof Error) {
        setError(e.message);
      } else {
        setError("Не удалось создать файл");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const onUpdate = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!editingId) {
      return;
    }

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      await updateFile(editingId, editForm);
      await loadData();
      resetEditForm();
      setMessage("Файл обновлен");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось обновить файл");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Файлы</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileCode2 className="h-5 w-5" />
            Файлы
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Тип</th>
                  <th className="px-3 py-2 font-medium">Имя</th>
                  <th className="px-3 py-2 font-medium">Версия</th>
                  <th className="px-3 py-2 font-medium">Путь</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.fileTypeDisplay}</td>
                    <td className="px-3 py-2">{item.name}</td>
                    <td className="px-3 py-2">{item.version}</td>
                    <td className="px-3 py-2 font-mono text-xs text-muted-foreground">{item.dataPath}</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2">
                        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>{editingItem ? `Изменение '${editingItem.name}'` : "Новый файл"}</CardDescription>
        </CardHeader>
        <CardContent>
          {!editingItem ? (
            <form className="space-y-3" onSubmit={(event) => void onCreate(event)}>
              <div className="space-y-1">
                <label className="text-sm">Наименование</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  value={createForm.name}
                  onChange={(event) => setCreateForm((prev) => ({ ...prev, name: event.target.value }))}
                />
              </div>

              <div className="space-y-1">
                <label className="text-sm">Версия</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  value={createForm.version}
                  onChange={(event) => setCreateForm((prev) => ({ ...prev, version: event.target.value }))}
                  required
                />
              </div>

              <div className="space-y-1">
                <label className="text-sm">Файл</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  type="file"
                  accept=".cf,.cfe,.cfu,.epf,.ospx"
                  onChange={(event) =>
                    setCreateForm((prev) => ({
                      ...prev,
                      file: event.target.files?.[0] ?? null,
                    }))
                  }
                  required
                />
              </div>

              {error && <div className="text-sm text-destructive">{error}</div>}
              {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

              <Button type="submit" disabled={isSaving}>
                <Plus className="h-4 w-4" />
                Создать
              </Button>
            </form>
          ) : (
            <form className="space-y-3" onSubmit={(event) => void onUpdate(event)}>
              <div className="space-y-1">
                <label className="text-sm">Наименование</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  value={editForm.name}
                  onChange={(event) => setEditForm((prev) => ({ ...prev, name: event.target.value }))}
                  required
                />
              </div>

              <div className="space-y-1">
                <label className="text-sm">Версия</label>
                <input
                  className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  value={editForm.version}
                  onChange={(event) => setEditForm((prev) => ({ ...prev, version: event.target.value }))}
                  required
                />
              </div>

              {error && <div className="text-sm text-destructive">{error}</div>}
              {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

              <div className="flex gap-2">
                <Button type="submit" disabled={isSaving}>
                  <Pencil className="h-4 w-4" />
                  Сохранить
                </Button>
                <Button type="button" variant="outline" onClick={resetEditForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              </div>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

