"use client";

import Link from "next/link";
import { AlertTriangle, FolderGit2, Pencil, Plus, RefreshCcw, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createGitRepository,
  deleteGitRepository,
  getGitRepositories,
  getGitTokens,
  type GitRepositoryListItem,
  type GitTokenItem,
  updateGitRepository,
} from "@/lib/api/git-repositories";

type FormState = {
  name: string;
  address: string;
  tokenId: string;
};

const initialFormState: FormState = {
  name: "",
  address: "",
  tokenId: "",
};

type GitRepositoriesPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function GitRepositoriesPage({ searchParams }: GitRepositoriesPageProps) {
  const [items, setItems] = useState<GitRepositoryListItem[]>([]);
  const [tokens, setTokens] = useState<GitTokenItem[]>([]);
  const [gitSyncEnabled, setGitSyncEnabled] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const [reposData, tokensData] = await Promise.all([getGitRepositories(), getGitTokens()]);
      setItems(reposData.items);
      setGitSyncEnabled(reposData.gitSyncEnabled);
      setTokens(tokensData);

      setForm((prev) => ({
        ...prev,
        tokenId: prev.tokenId || tokensData[0]?.id || "",
      }));
    } catch {
      setError("Не удалось загрузить git репозитории");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm({
      ...initialFormState,
      tokenId: tokens[0]?.id || "",
    });
  }, [tokens]);

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Репозиторий для редактирования не найден");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const onEdit = (item: GitRepositoryListItem) => {
    setEditingId(item.id);
    setMessage(null);
    setError(null);
    setForm({
      name: item.name,
      address: item.address,
      tokenId: item.tokenId,
    });
  };

  const onDelete = async (item: GitRepositoryListItem) => {
    const shouldDelete = window.confirm(`Удалить репозиторий '${item.name}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteGitRepository(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Репозиторий удален");
    } catch {
      setError("Не удалось удалить репозиторий");
    }
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      if (editingId) {
        await updateGitRepository(editingId, form);
        setMessage("Репозиторий обновлен");
      } else {
        await createGitRepository(form);
        setMessage("Репозиторий создан");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить репозиторий");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Git репозитории</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FolderGit2 className="h-5 w-5" />
            Git репозитории
          </CardTitle>
          <CardDescription>
            Всего: {items.length}. Синхронизация: {gitSyncEnabled ? "включена" : "выключена"}
          </CardDescription>
          <div className="px-6 pb-4 flex gap-2">
            <Button asChild variant="outline" size="sm">
              <Link href="/gitrepositories/gitsynctasks">
                <RefreshCcw className="h-4 w-4" />
                Задачи синхронизации
              </Link>
            </Button>
            <Button asChild variant="outline" size="sm">
              <Link href="/gitrepositories/gitsyncsettings">
                <RefreshCcw className="h-4 w-4" />
                Настройки синхронизации
              </Link>
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Имя</th>
                  <th className="px-3 py-2 font-medium">Адрес</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.name}</td>
                    <td className="px-3 py-2">{item.address}</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2">
                        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>
            {editingItem ? `Изменение '${editingItem.name}'` : "Новый репозиторий GIT"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Наименование</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.name}
                onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Адрес</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.address}
                onChange={(event) => setForm((prev) => ({ ...prev, address: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Токен</label>
              <select
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.tokenId}
                onChange={(event) => setForm((prev) => ({ ...prev, tokenId: event.target.value }))}
                required
              >
                {tokens.map((token) => (
                  <option key={token.id} value={token.id}>
                    {token.name}
                  </option>
                ))}
              </select>
            </div>

            {error && <div className="text-sm text-destructive">{error}</div>}
            {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

            <div className="flex gap-2">
              <Button type="submit" disabled={isSaving || tokens.length === 0}>
                <Plus className="h-4 w-4" />
                {editingItem ? "Сохранить" : "Создать"}
              </Button>
              {editingItem && (
                <Button type="button" variant="outline" onClick={resetForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

