"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { AlertTriangle, Copy, FileText, Pencil, Play, Plus, Trash2, Wrench, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createMaintenanceTask,
  deleteMaintenanceTask,
  getMaintenanceTaskTemplate,
  getMaintenanceTaskTemplatesLookup,
  getMaintenanceTasks,
  startMaintenanceTask,
  type MaintenanceTaskListItem,
  type MaintenanceTaskTemplateLookupItem,
  type UpsertMaintenanceTaskRequest,
  updateMaintenanceTask,
} from "@/lib/api/maintenance-tasks";

const EMPTY_DATE = "0001-01-01T00:00:00";

type FormState = {
  description: string;
  startDateTime: string;
  finishDateTime: string;
  isFaulted: boolean;
};

const initialFormState: FormState = {
  description: "",
  startDateTime: "",
  finishDateTime: "",
  isFaulted: false,
};

function isEmptyDate(value: string) {
  return value.startsWith("0001-01-01");
}

function getTaskState(task: { startDateTime: string; finishDateTime: string; isFaulted: boolean }) {
  if (isEmptyDate(task.startDateTime)) {
    return "Новая";
  }

  if (isEmptyDate(task.finishDateTime)) {
    return "Выполняется";
  }

  return task.isFaulted ? "Завершена с ошибками" : "Завершена успешно";
}

function formatDate(value: string) {
  if (isEmptyDate(value)) {
    return "—";
  }

  return new Date(value).toLocaleString("ru-RU");
}

function toInputDateTime(value: string) {
  if (isEmptyDate(value)) {
    return "";
  }

  const date = new Date(value);
  const offsetMs = date.getTimezoneOffset() * 60 * 1000;
  return new Date(date.getTime() - offsetMs).toISOString().slice(0, 16);
}

type MaintenanceTasksPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function MaintenanceTasksPage({ searchParams }: MaintenanceTasksPageProps) {
  const router = useRouter();
  const [items, setItems] = useState<MaintenanceTaskListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [templates, setTemplates] = useState<MaintenanceTaskTemplateLookupItem[]>([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>("");
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const [tasksData, templatesData] = await Promise.all([
        getMaintenanceTasks(),
        getMaintenanceTaskTemplatesLookup(),
      ]);
      setItems(tasksData);
      setTemplates(templatesData);
    } catch {
      setError("Не удалось загрузить задачи обслуживания");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const run = async () => {
      await loadData();
    };

    void run();
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onEdit = (item: MaintenanceTaskListItem) => {
    setEditingId(item.id);
    setForm({
      description: item.description,
      startDateTime: toInputDateTime(item.startDateTime),
      finishDateTime: toInputDateTime(item.finishDateTime),
      isFaulted: item.isFaulted,
    });
    setError(null);
    setMessage(null);
  };

  const onDelete = async (item: MaintenanceTaskListItem) => {
    const shouldDelete = window.confirm(`Удалить задачу '${item.description}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteMaintenanceTask(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Задача удалена");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось удалить задачу");
      }
    }
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Задача для редактирования не найдена");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const toIsoOrEmptyDate = (value: string) => (value ? new Date(value).toISOString() : EMPTY_DATE);

  const onStart = async (item: MaintenanceTaskListItem) => {
    setError(null);
    setMessage(null);

    try {
      await startMaintenanceTask(item.id);
      await loadData();
      setMessage("Задача запущена");
      router.push(`/maintenancetasks/${item.id}/log`);
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось запустить задачу");
      }
    }
  };

  const onCreateFromTemplate = async () => {
    if (!selectedTemplateId) {
      setError("Выберите шаблон");
      return;
    }

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      const template = await getMaintenanceTaskTemplate(selectedTemplateId);
      await createMaintenanceTask({
        description: template.description,
        startDateTime: EMPTY_DATE,
        finishDateTime: EMPTY_DATE,
        isFaulted: false,
      });
      await loadData();
      setMessage("Задача создана из шаблона");
      setSelectedTemplateId("");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось создать задачу из шаблона");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    const payload: UpsertMaintenanceTaskRequest = {
      description: form.description,
      startDateTime: toIsoOrEmptyDate(form.startDateTime),
      finishDateTime: toIsoOrEmptyDate(form.finishDateTime),
      isFaulted: form.isFaulted,
    };

    try {
      if (editingId) {
        await updateMaintenanceTask(editingId, payload);
        setMessage("Задача обновлена");
      } else {
        await createMaintenanceTask(payload);
        setMessage("Задача создана");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить задачу");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Задачи обслуживания</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Wrench className="h-5 w-5" />
            Задачи обслуживания
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
          <div className="px-6 pb-4 flex flex-wrap items-center gap-2">
            <div className="flex items-center gap-2">
              <select
                className="h-9 rounded-md border bg-background px-3 text-sm"
                value={selectedTemplateId}
                onChange={(event) => setSelectedTemplateId(event.target.value)}
              >
                <option value="">Выберите шаблон</option>
                {templates.map((template) => (
                  <option key={template.id} value={template.id}>
                    {template.description}
                  </option>
                ))}
              </select>
              <Button type="button" variant="outline" size="sm" onClick={() => void onCreateFromTemplate()} disabled={isSaving}>
                <Plus className="h-4 w-4" />
                Из шаблона
              </Button>
            </div>
            <Button asChild variant="outline" size="sm">
              <Link href="/maintenancetaskstemplates">
                <Copy className="h-4 w-4" />
                Шаблоны задач
              </Link>
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Описание</th>
                  <th className="px-3 py-2 font-medium">Начало</th>
                  <th className="px-3 py-2 font-medium">Окончание</th>
                  <th className="px-3 py-2 font-medium">Состояние</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
