"use client";

import Link from "next/link";
import { AlertTriangle, Download, Pencil, Plus, Trash2, Upload, Wrench, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createMaintenanceTaskTemplate,
  deleteMaintenanceTaskTemplate,
  exportMaintenanceTaskTemplate,
  getMaintenanceTaskTemplates,
  importMaintenanceTaskTemplate,
  type MaintenanceTaskListItem,
  type UpsertMaintenanceTaskRequest,
  updateMaintenanceTaskTemplate,
} from "@/lib/api/maintenance-tasks";

const EMPTY_DATE = "0001-01-01T00:00:00";

type FormState = {
  description: string;
  startDateTime: string;
  finishDateTime: string;
  isFaulted: boolean;
};

const initialFormState: FormState = {
  description: "",
  startDateTime: "",
  finishDateTime: "",
  isFaulted: false,
};

function isEmptyDate(value: string) {
  return value.startsWith("0001-01-01");
}

function getTemplateState(task: { startDateTime: string; finishDateTime: string; isFaulted: boolean }) {
  if (isEmptyDate(task.startDateTime)) {
    return "Новая";
  }

  if (isEmptyDate(task.finishDateTime)) {
    return "Выполняется";
  }

  return task.isFaulted ? "Завершена с ошибками" : "Завершена успешно";
}

function formatDate(value: string) {
  if (isEmptyDate(value)) {
    return "—";
  }

  return new Date(value).toLocaleString("ru-RU");
}

type MaintenanceTaskTemplatesPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default function MaintenanceTaskTemplatesPage({ searchParams }: MaintenanceTaskTemplatesPageProps) {
  const [items, setItems] = useState<MaintenanceTaskListItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedCreate, setRequestedCreate] = useState(false);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const data = await getMaintenanceTaskTemplates();
      setItems(data);
    } catch {
      setError("Не удалось загрузить шаблоны задач обслуживания");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const create = params.create;
        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      void loadData();
    }, 0);

    return () => clearTimeout(timeoutId);
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onDelete = async (item: MaintenanceTaskListItem) => {
    const shouldDelete = window.confirm(`Удалить шаблон '${item.description}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteMaintenanceTaskTemplate(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Шаблон удален");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось удалить шаблон");
      }
    }
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (!requestedCreate || editingId) {
      return;
    }

    resetForm();
    setRequestedCreate(false);
  }, [requestedCreate, editingId, items, resetForm]);

  const toIsoOrEmptyDate = (value: string) => (value ? new Date(value).toISOString() : EMPTY_DATE);

  const onImportClick = () => {
    fileInputRef.current?.click();
  };

  const onImportFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";

    if (!file) {
      return;
    }

    setIsSaving(true);
    setError(null);
    setMessage(null);

    try {
      await importMaintenanceTaskTemplate(file);
      await loadData();
      setMessage("Шаблон импортирован");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось импортировать шаблон");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const onExport = async (item: MaintenanceTaskListItem) => {
    setError(null);
    setMessage(null);

    try {
      const blob = await exportMaintenanceTaskTemplate(item.id);
      const url = URL.createObjectURL(blob);
      const anchorElement = document.createElement("a");
      anchorElement.href = url;
      anchorElement.download = "task_template.json";
      anchorElement.click();
      anchorElement.remove();
      URL.revokeObjectURL(url);
      setMessage("Шаблон выгружен");
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось выгрузить шаблон");
      }
    }
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    const payload: UpsertMaintenanceTaskRequest = {
      description: form.description,
      startDateTime: toIsoOrEmptyDate(form.startDateTime),
      finishDateTime: toIsoOrEmptyDate(form.finishDateTime),
      isFaulted: form.isFaulted,
    };

    try {
      if (editingId) {
        await updateMaintenanceTaskTemplate(editingId, payload);
        setMessage("Шаблон обновлен");
      } else {
        await createMaintenanceTaskTemplate(payload);
        setMessage("Шаблон создан");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить шаблон");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Шаблоны задач обслуживания</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Wrench className="h-5 w-5" />
            Шаблоны задач обслуживания
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
          <div className="px-6 pb-4">
            <input
              ref={fileInputRef}
              type="file"
              accept="application/json,.json"
              className="hidden"
              onChange={(event) => void onImportFileChange(event)}
            />
            <Button type="button" variant="outline" size="sm" onClick={onImportClick} disabled={isSaving}>
              <Upload className="h-4 w-4" />
              Импорт JSON
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Описание</th>
                  <th className="px-3 py-2 font-medium">Начало</th>
                  <th className="px-3 py-2 font-medium">Окончание</th>
