                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>
            {editingItem ? `Изменение '${editingItem.description}'` : "Новый шаблон задачи обслуживания"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Описание</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
