"use client";

import Link from "next/link";
import { AlertTriangle, FileCode2, FileText, Pencil, Plus, Settings, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ApiError } from "@/lib/api/client";
import {
  createTechLogSeance,
  deleteTechLogSeance,
  getTechLogSeanceLookups,
  getTechLogSeances,
  type TechLogLookupItem,
  type TechLogSeanceListItem,
  type TechLogSeanceStartMode,
  updateTechLogSeance,
} from "@/lib/api/techlog-seances";

type FormState = {
  description: string;
  startMode: TechLogSeanceStartMode;
  startDateTime: string;
  duration: number;
  agentIds: string[];
  templateIds: string[];
};

const initialFormState: FormState = {
  description: "",
  startMode: "Immediately",
  startDateTime: "",
  duration: 15,
  agentIds: [],
  templateIds: [],
};

type TechLogSeancesPageProps = {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

function formatDate(value: string) {
  if (value.startsWith("0001-01-01")) {
    return "—";
  }

  return new Date(value).toLocaleString("ru-RU");
}

function toLocalDateTimeInput(value: string) {
  if (!value || value.startsWith("0001-01-01")) {
    return "";
  }

  const date = new Date(value);
  const offsetMs = date.getTimezoneOffset() * 60 * 1000;
  return new Date(date.getTime() - offsetMs).toISOString().slice(0, 16);
}

export default function TechLogSeancesPage({ searchParams }: TechLogSeancesPageProps) {
  const [items, setItems] = useState<TechLogSeanceListItem[]>([]);
  const [agentOptions, setAgentOptions] = useState<TechLogLookupItem[]>([]);
  const [templateOptions, setTemplateOptions] = useState<TechLogLookupItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(initialFormState);
  const [requestedEditId, setRequestedEditId] = useState<string | null>(null);
  const [requestedCreate, setRequestedCreate] = useState(false);

  const editingItem = useMemo(
    () => (editingId ? items.find((item) => item.id === editingId) : undefined),
    [editingId, items]
  );

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const [data, lookups] = await Promise.all([getTechLogSeances(), getTechLogSeanceLookups()]);
      setItems(data);
      setAgentOptions(lookups.agents);
      setTemplateOptions(lookups.templates);
    } catch {
      setError("Не удалось загрузить сеансы техжурнала");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    let cancelled = false;

    if (searchParams) {
      void searchParams.then((params) => {
        if (cancelled) {
          return;
        }

        const editId = params.editId;
        const create = params.create;

        setRequestedEditId(Array.isArray(editId) ? (editId[0] ?? null) : (editId ?? null));

        const createValue = Array.isArray(create) ? (create[0] ?? "") : (create ?? "");
        setRequestedCreate(createValue === "1" || createValue.toLowerCase() === "true");
      });
    }

    return () => {
      cancelled = true;
    };
  }, [searchParams]);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      void loadData();
    }, 0);

    return () => clearTimeout(timeoutId);
  }, [loadData]);

  const resetForm = useCallback(() => {
    setEditingId(null);
    setForm(initialFormState);
  }, []);

  const onEdit = (item: TechLogSeanceListItem) => {
    setEditingId(item.id);
    setError(null);
    setMessage(null);
    setForm({
      description: item.description,
      startMode: item.startMode,
      startDateTime: toLocalDateTimeInput(item.startDateTime),
      duration: item.duration,
      agentIds: [...item.agentIds],
      templateIds: [...item.templateIds],
    });
  };

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    if (requestedCreate && !editingId) {
      resetForm();
      setRequestedCreate(false);
      setRequestedEditId(null);
      return;
    }

    if (!requestedEditId || editingId) {
      return;
    }

    const target = items.find((item) => item.id === requestedEditId);
    if (!target) {
      setError("Сеанс для редактирования не найден");
      setRequestedEditId(null);
      return;
    }

    onEdit(target);
    setRequestedEditId(null);
    setRequestedCreate(false);
  }, [requestedCreate, requestedEditId, editingId, items, resetForm]);

  const onDelete = async (item: TechLogSeanceListItem) => {
    const shouldDelete = window.confirm(`Удалить сеанс '${item.description}'?`);
    if (!shouldDelete) {
      return;
    }

    setError(null);
    setMessage(null);

    try {
      await deleteTechLogSeance(item.id);
      await loadData();
      if (editingId === item.id) {
        resetForm();
      }
      setMessage("Сеанс удален");
    } catch {
      setError("Не удалось удалить сеанс");
    }
  };

  const buildStartDateTime = () => {
    if (form.startMode === "Scheduled") {
      return form.startDateTime ? new Date(form.startDateTime).toISOString() : new Date(0).toISOString();
    }

    return new Date(0).toISOString();
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    setIsSaving(true);
    setError(null);
    setMessage(null);

    if (form.agentIds.length === 0) {
      setIsSaving(false);
      setError("Не указаны подключаемые агенты");
      return;
    }

    if (form.templateIds.length === 0) {
      setIsSaving(false);
      setError("Не указаны подключаемые шаблоны");
      return;
    }

    if (form.startMode === "Scheduled" && !form.startDateTime) {
      setIsSaving(false);
      setError("Для запланированного запуска укажите дату и время начала");
      return;
    }

    if (form.startMode === "Scheduled" && new Date(form.startDateTime).getTime() <= Date.now()) {
      setIsSaving(false);
      setError("Дата и время начала не могут быть меньше текущей даты");
      return;
    }

    if (form.startMode !== "Monitor" && form.duration <= 1) {
      setIsSaving(false);
      setError("Длительность не может быть меньше 1 минуты");
      return;
    }

    try {
      const payload = {
        description: form.description,
        startMode: form.startMode,
        startDateTime: buildStartDateTime(),
        duration: form.duration,
        agentIds: form.agentIds,
        templateIds: form.templateIds,
      };

      if (editingId) {
        await updateTechLogSeance(editingId, payload);
        setMessage("Сеанс обновлен");
      } else {
        await createTechLogSeance(payload);
        setMessage("Сеанс создан");
      }

      await loadData();
      resetForm();
    } catch (e) {
      if (e instanceof ApiError && typeof e.details === "string") {
        setError(e.details);
      } else {
        setError("Не удалось сохранить сеанс");
      }
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Техжурнал: сеансы</CardTitle>
          <CardDescription>Загрузка...</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  if (error && items.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-5 w-5" />
            {error}
          </CardTitle>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Техжурнал: сеансы
          </CardTitle>
          <CardDescription>Всего: {items.length}</CardDescription>
          <div className="px-6 pb-4 flex gap-2">
            <Button asChild variant="outline" size="sm">
              <Link href="/techlog/templates">
                <FileCode2 className="h-4 w-4" />
                Шаблоны
              </Link>
            </Button>
            <Button asChild variant="outline" size="sm">
              <Link href="/techlog/settings">
                <Settings className="h-4 w-4" />
                Настройки
              </Link>
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Описание</th>
                  <th className="px-3 py-2 font-medium">Режим</th>
                  <th className="px-3 py-2 font-medium">Начало</th>
                  <th className="px-3 py-2 font-medium">Длительность (мин)</th>
                  <th className="px-3 py-2 font-medium">Действия</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="border-t">
                    <td className="px-3 py-2">{item.description}</td>
                    <td className="px-3 py-2">{item.startModeDisplay}</td>
                    <td className="px-3 py-2">{formatDate(item.startDateTime)}</td>
                    <td className="px-3 py-2">{item.duration}</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2">
                        <Button asChild type="button" variant="outline" size="sm">
                          <Link href={`/techlog/seances/${item.id}/log`}>
                            <FileText className="h-4 w-4" />
                          </Link>
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => onEdit(item)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button type="button" variant="outline" size="sm" onClick={() => void onDelete(item)}>
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{editingItem ? "Редактировать" : "Создать"}</CardTitle>
          <CardDescription>
            {editingItem ? `Изменение '${editingItem.description}'` : "Новый сеанс техжурнала"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form className="space-y-3" onSubmit={(event) => void onSubmit(event)}>
            <div className="space-y-1">
              <label className="text-sm">Описание</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.description}
                onChange={(event) => setForm((prev) => ({ ...prev, description: event.target.value }))}
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Режим запуска</label>
              <select
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                value={form.startMode}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    startMode: event.target.value as TechLogSeanceStartMode,
                  }))
                }
              >
                <option value="Immediately">При создании</option>
                <option value="Monitor">Мониторинг</option>
                <option value="Scheduled">Запланирован</option>
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-sm">Дата и время начала</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                type="datetime-local"
                value={form.startDateTime}
                onChange={(event) => setForm((prev) => ({ ...prev, startDateTime: event.target.value }))}
                disabled={form.startMode !== "Scheduled"}
                required={form.startMode === "Scheduled"}
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Длительность (мин.)</label>
              <input
                className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                type="number"
                min={1}
                value={form.duration}
                onChange={(event) => setForm((prev) => ({ ...prev, duration: Number(event.target.value) || 0 }))}
                required
                disabled={form.startMode === "Monitor"}
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm">Агенты</label>
              <select
                className="min-h-28 w-full rounded-md border bg-background px-3 py-2 text-sm"
                multiple
                value={form.agentIds}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    agentIds: Array.from(event.target.selectedOptions, (option) => option.value),
                  }))
                }
                required
              >
                {agentOptions.map((option) => (
                  <option key={option.id} value={option.id}>
                    {option.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-sm">Шаблоны сбора</label>
              <select
                className="min-h-28 w-full rounded-md border bg-background px-3 py-2 text-sm"
                multiple
                value={form.templateIds}
                onChange={(event) =>
                  setForm((prev) => ({
                    ...prev,
                    templateIds: Array.from(event.target.selectedOptions, (option) => option.value),
                  }))
                }
                required
              >
                {templateOptions.map((option) => (
                  <option key={option.id} value={option.id}>
                    {option.name}
                  </option>
                ))}
              </select>
            </div>

            {error && <div className="text-sm text-destructive">{error}</div>}
            {message && <div className="text-sm text-emerald-600 dark:text-emerald-500">{message}</div>}

            <div className="flex gap-2">
              <Button type="submit" disabled={isSaving}>
                <Plus className="h-4 w-4" />
                {editingItem ? "Сохранить" : "Создать"}
              </Button>
              {editingItem && (
                <Button type="button" variant="outline" onClick={resetForm}>
                  <X className="h-4 w-4" />
                  Отмена
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

